mapper.insert:
insert into tb_media_asset(
    object_key, purpose, visibility, owner_type, owner_id, status,
    mime_type, file_size, width, height, expires_at, delete_after,
    delete_retry_count, sort_order, create_time, update_time
) values(
    #{objectKey}, #{purpose}, #{visibility}, #{ownerType}, #{ownerId}, #{status},
    #{mimeType}, #{fileSize}, #{width}, #{height}, #{expiresAt}, #{deleteAfter},
    #{deleteRetryCount}, #{sortOrder}, #{createTime}, #{updateTime}
)

mapper.select:
select count(*)
from tb_media_asset
where owner_type = #{ownerType}
  and owner_id = #{ownerId}
  and status in ('UPLOADING', 'TEMP')

mapper.update:
update tb_media_asset
set sort_order = #{sortOrder},
    update_time = #{updateTime}
where id = #{id}
  and bound_type = #{boundType}
  and bound_id = #{boundId}
  and status = 'BOUND'

mapper.select:
select * from tb_media_asset
where bound_type = #{boundType} and purpose = #{purpose}
  and status = 'BOUND' and visibility = 'PUBLIC'
  and bound_id in
  #{id}
order by bound_id asc, sort_order asc, id asc

select * from tb_media_asset
where bound_type = #{boundType} and purpose = #{purpose}
  and status = 'BOUND' and visibility in ('PUBLIC', 'PRIVATE')
  and bound_id in
  #{id}
order by bound_id asc, sort_order asc, id asc

select *
from tb_media_asset
where bound_type = #{boundType}
  and bound_id = #{boundId}
  and purpose = #{purpose}
  and status = 'BOUND'
order by sort_order asc, id asc

mapper.update:
update tb_media_asset
set status = 'PENDING_DELETE',
    delete_after = #{deleteAfter},
    update_time = #{updateTime}
where id = #{id}
  and owner_type = #{ownerType}
  and owner_id = #{ownerId}
  and status in ('UPLOADING', 'TEMP', 'FAILED')

update tb_media_asset
set status = 'PENDING_DELETE',
    delete_after = #{deleteAfter},
    update_time = #{updateTime}
where id = #{id}
  and status = 'BOUND'

update tb_media_asset
set status = 'PENDING_DELETE',
    delete_after = #{now},
    update_time = #{now}
where id = #{id}
  and (
      (status = 'TEMP' and expires_at <= #{now})
      or (status in ('UPLOADING', 'PENDING_DELETE', 'FAILED') and delete_after <= #{now})
  )
